test('actual readiness transition atomically commits a marker and rolls it back on interruption',{skip:process.platform!=='linux'},t=>{
  const f=fixture(t),script="const fs=require('node:fs'),{DatabaseSync}=require('node:sqlite'),db=new DatabaseSync(process.argv[1]);db.exec('BEGIN IMMEDIATE');db.prepare(\"UPDATE model_outputs SET status='ready' WHERE id=?\").run(process.argv[3]);db.prepare(\"UPDATE model_versions SET status='ready' WHERE id=?\").run(process.argv[3]);db.prepare(\"UPDATE processing_attempts SET status='ready_for_review' WHERE id=?\").run(process.argv[2]);fs.writeSync(1,String(db.prepare('SELECT COUNT(*) n FROM native_ingest_commit_candidate').get().n));process.kill(process.pid,'SIGKILL');";
  const child=spawnSync(process.execPath,['-e',script,f.file,f.attempt.id,f.version],{encoding:'utf8',timeout:5000});assert.equal(child.signal,'SIGKILL',child.stderr);assert.equal(child.stdout,'1');assert.equal(f.db.prepare('SELECT COUNT(*) n FROM native_ingest_commit_candidate').get().n,0);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ingesting');assert.equal(f.processing.getModelOutput(f.version).status,'staged');
  const savedArchive=f.db.prepare('SELECT archive_json FROM processing_attempt_transfer_provenance WHERE attempt_id=?').get(f.attempt.id).archive_json;f.db.prepare('UPDATE processing_attempt_transfer_provenance SET archive_json=NULL WHERE attempt_id=?').run(f.attempt.id);assert.throws(()=>f.processing.completeOutputForReview(f.attempt.id,{jobId:f.job.id,owner:'owner',event:{eventId:'event-test'}}),/ingestion commit evidence unavailable/);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ingesting');assert.equal(f.db.prepare('SELECT COUNT(*) n FROM native_ingest_commit_candidate').get().n,0);f.db.prepare('UPDATE processing_attempt_transfer_provenance SET archive_json=? WHERE attempt_id=?').run(savedArchive,f.attempt.id);
  f.db.exec("CREATE TRIGGER synthetic_fail_ready BEFORE UPDATE OF status ON processing_tasks WHEN NEW.status='ready_for_review' BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");assert.throws(()=>f.processing.completeOutputForReview(f.attempt.id,{jobId:f.job.id,owner:'owner',event:{eventId:'event-test'}}));assert.equal(f.db.prepare('SELECT COUNT(*) n FROM native_ingest_commit_candidate').get().n,0);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ingesting');f.db.exec('DROP TRIGGER synthetic_fail_ready');
  assert.equal(f.processing.completeOutputForReview(f.attempt.id,{jobId:f.job.id,owner:'owner',event:{eventId:'event-test'}}).status,'ready_for_review');const marker=candidate.read(f.db,f.attempt.id,true);assert.match(marker.commit_id,/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/);assert.equal(marker.provider_task_id,f.attempt.providerTaskId);assert.equal(marker.archive_sha256,f.archive.archiveSha256);assert.equal(marker.model_version_id,f.version);assert.equal(f.processing.completeOutputForReview(f.attempt.id,{jobId:f.job.id,owner:'owner',event:{eventId:'event-test'}}),null);assert.deepEqual(candidate.read(f.db,f.attempt.id,true),marker);assert.throws(()=>f.db.prepare('DELETE FROM native_ingest_commit_candidate WHERE attempt_id=?').run(f.attempt.id),/immutable/);
  const other=openDatabase(f.file);try{assert.deepEqual(candidate.read(other,f.attempt.id,true),marker);}finally{other.close();}
});
