test('readiness candidate preserves event and audit atomically and rejects changed replay',t=>{
  const f=fixture(t),broker=require('../server/nativeReadinessBrokerCandidate');broker.install(f.db,true);
  const request={requestId:crypto.randomUUID(),attemptId:f.attempt.id,jobId:f.job.id,owner:'owner',ingestedAt:new Date().toISOString(),event:{eventId:`processing-ready-${f.attempt.id}`,schemaVersion:1,type:'processing.ready_for_review',projectId:f.task.projectId,projectDisplayName:'Synthetic',taskId:f.task.id,taskDisplayName:'Test',attemptId:f.attempt.id,requestedBySubject:null,status:'ready_for_review',reviewUrl:`https://example.test/operations/processing?attemptId=${f.attempt.id}`}};
  const allowed={authorize:()=>true,reviewBaseUrl:'https://example.test'};assert.throws(()=>broker.complete(f.db,request),/hold/);assert.throws(()=>broker.complete(f.db,{...request,owner:'wrong'},allowed),/hold/);assert.throws(()=>broker.complete(f.db,{...request,event:{...request.event,projectDisplayName:'Forged'}},allowed),/hold/);assert.throws(()=>broker.complete(f.db,{...request,event:{...request.event,reviewUrl:'https://evil.test/'}},allowed),/hold/);const lease=f.db.prepare('SELECT lease_expires_at FROM processing_jobs WHERE id=?').get(f.job.id).lease_expires_at;f.db.prepare("UPDATE processing_jobs SET lease_expires_at='2000-01-01T00:00:00.000Z' WHERE id=?").run(f.job.id);assert.throws(()=>broker.complete(f.db,request,allowed),/hold/);f.db.prepare('UPDATE processing_jobs SET lease_expires_at=? WHERE id=?').run(lease,f.job.id);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ingesting');
  f.db.exec("CREATE TRIGGER synthetic_receipt_failure BEFORE INSERT ON audit_events WHEN NEW.action='processing_attempt.ready_for_review' BEGIN SELECT RAISE(ABORT,'receipt failure'); END");assert.throws(()=>broker.complete(f.db,request,allowed),/receipt failure/);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ingesting');assert.equal(f.db.prepare('SELECT COUNT(*) n FROM event_outbox WHERE id=?').get(request.event.eventId).n,0);f.db.exec('DROP TRIGGER synthetic_receipt_failure');
  const result=broker.complete(f.db,request,allowed);assert.equal(f.processing.getAttempt(f.attempt.id).status,'ready_for_review');const stored=JSON.parse(f.db.prepare('SELECT payload_json FROM event_outbox WHERE id=?').get(request.event.eventId).payload_json);for(const [key,value] of Object.entries(request.event))assert.deepEqual(stored[key],value);assert.equal(f.db.prepare("SELECT COUNT(*) n FROM audit_events WHERE action='processing_attempt.ready_for_review' AND entity_id=?").get(f.attempt.id).n,1);assert.deepEqual(broker.complete(f.db,request,allowed),result);const reopened=openDatabase(f.file);try{assert.deepEqual(broker.complete(reopened,request,allowed),result);}finally{reopened.close();}assert.throws(()=>broker.complete(f.db,{...request,ingestedAt:'2026-01-01T00:00:00Z'},allowed),/hold/);assert.throws(()=>broker.complete(f.db,{...request,requestId:crypto.randomUUID()},allowed),/hold/);assert.throws(()=>broker.complete(f.db,request,{authorize:()=>false}),/hold/);
  f.db.exec('DROP TRIGGER native_readiness_receipt_candidate_no_update');assert.throws(()=>broker.complete(f.db,request,allowed),/hold/);assert.throws(()=>broker.install(f.db,true),/hold/);
});
