test('partial native staging retries in a new journaled run and preserves old bytes',async t=>{
  const f=fixture(t),native=require('../server/nativeReferenceReceiptCandidate'),{stageAndHold,recoverAndHold}=require('../server/nativeReferenceConsumerCandidate');native.install(f.db,true);const binding={attemptId:f.attempt.id,bindingId:crypto.randomUUID(),jobId:'job_1',generation:2,environment:'staging',inputManifestSha256:'c'.repeat(64),pipelineDigest:'b'.repeat(64)};native.bind(f.db,binding,{authorizeBinding:()=>true});const root=path.join(f.root,'retry-results');fs.mkdirSync(root,{mode:0o700});const bytes=Buffer.from('abc'),objectSha=sha(bytes),manifest={schemaVersion:1,jobId:'job_1',generation:2,environment:'staging',engineVersions:{odm:'3.5.6'},objects:[{id:'o1',role:'pointcloud',byteSize:3,sha256:objectSha}],pipelineDigest:'b'.repeat(64),resultManifestSha256:'bc94d06bd54cfd8208c7d8fd21d82eaaef6354bf352b265afdb74ec6db4ba43a'},headers=new Headers({'content-length':'3','x-result-sha256':objectSha,'x-result-manifest-sha256':manifest.resultManifestSha256}),partial=async function*(){yield bytes.subarray(0,2);throw new Error('interrupted');},complete=async function*(){yield bytes;},first=crypto.randomUUID(),second=crypto.randomUUID(),base={db:f.db,attemptId:f.attempt.id,root,storageReceiptId:crypto.randomUUID(),receiptId:crypto.randomUUID(),manifest,maxBytes:1024,acceptedAt:'2026-11-01T00:00:00.000Z',authorizeBinding:()=>true,authorizeReceipt:()=>true,enabled:true};await assert.rejects(stageAndHold({...base,stageId:first,openObject:async()=>({status:200,headers,source:partial(),close:async()=>{}})}),{code:'native_reference_storage_hold'});const oldFile=path.join(root,'receipt-'+base.storageReceiptId+'-run-'+first,'object-o1');assert.equal(fs.readFileSync(oldFile).toString(),'ab');assert.deepEqual(native.listRuns(f.db,f.attempt.id,{authorizeBinding:()=>true}),{runs:[{stageId:first,ordinal:1}],selectedStageId:null});assert.throws(()=>native.holdReceipt(f.db,{attemptId:f.attempt.id,storageReceiptId:base.storageReceiptId,receiptId:base.receiptId,stageId:first,manifest,objects:[{id:'o1',byteSize:3,sha256:objectSha}],acceptedAt:'2026-11-02T00:00:00.000Z'},{authorizeReceipt:()=>true,verifyDurableStorage:()=>true}));const out=await stageAndHold({...base,stageId:second,openObject:async()=>({status:200,headers,source:complete(),close:async()=>{}})});assert.equal(out.stageId,second);assert.equal(native.listRuns(f.db,f.attempt.id,{authorizeBinding:()=>true}).selectedStageId,second);assert.equal(fs.readFileSync(oldFile).toString(),'ab');assert.equal(f.db.prepare('SELECT stage_id FROM native_reference_stage_selection_candidate WHERE attempt_id=?').get(f.attempt.id).stage_id,second);await assert.rejects(recoverAndHold({...base,stageId:first}),{code:'native_reference_storage_hold'});assert.throws(()=>native.registerRun(f.db,f.attempt.id,crypto.randomUUID(),{authorizeBinding:()=>true}));for(const mode of ['OFF','ON']){f.db.exec('PRAGMA recursive_triggers='+mode);assert.throws(()=>f.db.prepare('INSERT OR REPLACE INTO native_reference_stage_selection_candidate VALUES(?,?)').run(f.attempt.id,first),/immutable/);assert.equal(f.db.prepare('SELECT stage_id FROM native_reference_stage_selection_candidate WHERE attempt_id=?').get(f.attempt.id).stage_id,second);}assert.throws(()=>native.registerRun(f.db,f.attempt.id,first,{authorizeBinding:()=>true}));
});
